    /// <summary>The contours of a letter, placed at a centre with the given capital height.</summary>
    public static IReadOnlyList<CubicPath> Place(char letter, PointD center, double height) =>
        Outlines[letter].Select(contour => ToPath(contour, center, height)).ToList();

    private static CubicPath ToPath(double[] contour, PointD center, double height)
    {
        PointD Point(int index) => new(center.X + contour[index] * height, center.Y + contour[index + 1] * height);

        var segments = new List<CubicSegment>((contour.Length - 2) / 6);
        for (int i = 2; i < contour.Length; i += 6)
        {
            segments.Add(new CubicSegment(Point(i), Point(i + 2), Point(i + 4)));
        }

        return new CubicPath(Point(0), segments);
    }
